-- Gabinet SaaS – migracja 3: katalog kodów NFZ (etap 4a)
-- Dane 1:1 z obecnej aplikacji (nfz.html: D, PTS, PTS_UNIT, PTS_NO15, PTS_NO08, NFZ_MIN, PTS_AN; commit ff60d5a).
-- Źródło wyceny (z aplikacji): Wycena: zał. 1c – Zarządzenie 95/2026/DSOZ (pakiety, od 1.09.2026); zał. 1b – Zarządzenie 44/2025/DSOZ (świadczenia jednostkowe). Współczynniki: § 12 ust. 2, 2a, 3 i § 13 ust. 1 pkt 5, 5a zarządzenia 60/2023/DSOZ z późn. zm.
-- valid_from: pakiety ST – 1.09.2026 (zał. 1c, 95/2026/DSOZ); świadczenia jednostkowe – data obowiązywania nieustalona
-- w obecnej aplikacji, dlatego NULL (do uzupełnienia przy weryfikacji z treścią zarządzenia).
BEGIN;
ALTER TABLE app.nfz_catalog ALTER COLUMN valid_from DROP NOT NULL;
COMMENT ON TABLE app.nfz_catalog IS 'Kody NFZ – tylko odczyt dla aplikacji; każdy wpis ze źródłem (zarządzenie DSOZ). definition: kind pkg|unit|anest, unit, no15 (§ 12 ust. 2a), no08 (§ 13 ust. 1 pkt 5a), minPerPkg, icd';
COMMIT;
